<?php
require_once __DIR__ . '/config/bootstrap.php';
require_once __DIR__ . '/config/auth.php';
require_staff();
if(!isset($_SESSION['user_id'])&&!isset($_SESSION['usuario_id'])){header('Location:login.php');exit;}require_once 'config/database.php';$db=getDBConnection();
$ini=$_GET['fecha_inicio']??date('Y-m-01');$fin=$_GET['fecha_fin']??date('Y-m-d');function vdate($d){$x=DateTime::createFromFormat('Y-m-d',$d);return $x&&$x->format('Y-m-d')===$d;}if(!vdate($ini)||!vdate($fin)||$ini>$fin){$ini=date('Y-m-01');$fin=date('Y-m-d');}
$q=$db->prepare("SELECT COUNT(*) cantidad,COALESCE(SUM(total),0) total,COALESCE(AVG(total),0) promedio FROM facturas WHERE estado='paid' AND fecha_emision BETWEEN ? AND ?");$q->execute([$ini.' 00:00:00',$fin.' 23:59:59']);$sum=$q->fetch(PDO::FETCH_ASSOC);
$q=$db->prepare("SELECT f.numero_factura,f.fecha_emision,c.nombre cliente,f.metodo_pago,f.total FROM facturas f LEFT JOIN clientes c ON c.id=f.cliente_id WHERE f.estado='paid' AND f.fecha_emision BETWEEN ? AND ? ORDER BY f.fecha_emision DESC");$q->execute([$ini.' 00:00:00',$fin.' 23:59:59']);$rows=$q->fetchAll(PDO::FETCH_ASSOC);
?><!doctype html><html lang="es"><head>
<?php if(function_exists('av_head')) av_head(); ?><meta charset="utf-8"><title>Reporte de ingresos</title><style>body{font-family:Arial;margin:35px;color:#222}.a{margin-bottom:20px}.b{background:#0f6c33;color:white;border:0;border-radius:7px;padding:9px 14px;text-decoration:none}.head{border-bottom:3px solid #0f6c33}.cards{display:flex;gap:14px;margin:22px 0}.c{border:1px solid #ddd;border-radius:10px;padding:16px;flex:1}.n{font-size:25px;font-weight:bold;color:#0f6c33}table{border-collapse:collapse;width:100%}th,td{padding:9px;border-bottom:1px solid #ddd;text-align:left}th{background:#f2f6f3}@media print{.a{display:none}}@media(max-width:650px){.cards{display:block}.c{margin-bottom:10px}}</style>    <link rel="stylesheet" href="css/app-optimized.css?v=20260812c">
</head><body><div class="a"><button class="b" onclick="print()">Imprimir / Guardar PDF</button> <a class="b" href="ingresos.php?fecha_inicio=<?=htmlspecialchars($ini)?>&fecha_fin=<?=htmlspecialchars($fin)?>">Volver</a></div><div class="head"><h1>Reporte de ingresos</h1><p><?=htmlspecialchars($ini)?> al <?=htmlspecialchars($fin)?></p></div><div class="cards"><div class="c">Total cobrado<div class="n">$<?=number_format((float)$sum['total'],2)?></div></div><div class="c">Facturas pagadas<div class="n"><?=(int)$sum['cantidad']?></div></div><div class="c">Ticket promedio<div class="n">$<?=number_format((float)$sum['promedio'],2)?></div></div></div><table><tr><th>Factura</th><th>Fecha</th><th>Cliente</th><th>Método</th><th>Total</th></tr><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['numero_factura'])?></td><td><?=htmlspecialchars($r['fecha_emision'])?></td><td><?=htmlspecialchars($r['cliente']??'')?></td><td><?=htmlspecialchars($r['metodo_pago']??'')?></td><td>$<?=number_format((float)$r['total'],2)?></td></tr><?php endforeach;?></table></body></html>
